import{_ as n,a0 as o,w as p,s as r,ao as d,I as l,x as s,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何更改 Linux 的 I/O 調度器 | LCTT x X-CMD","titleTemplate":false,"description":"如何更改 Linux 的 I/O 調度器 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何更改 Linux 的 I/O 調度器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何更改 Linux 的 I/O 調度器 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20160104 How to Change Linux IO Scheduler","title":"如何更改 Linux 的 I/O 調度器","tag":"201703","desc":""},"relativePath":"201703/20160104 How to Change Linux IO Scheduler.md","filePath":"[post].md"}'),u={name:"201703/20160104 How to Change Linux IO Scheduler.md"};function h(g,e,c,b,k,m){const i=o("Link");return p(),r("div",null,[e[13]||(e[13]=d(`<h1 id="如何更改-linux-的-i-o-調度器" tabindex="-1">如何更改 Linux 的 I/O 調度器 <a class="header-anchor" href="#如何更改-linux-的-i-o-調度器" aria-label="Permalink to “如何更改 Linux 的 I/O 調度器”">​</a></h1><p>Linux 的 I/O 調度器是一個從存儲卷以塊式 I/O 訪問的進程，有時也叫磁盤調度器。Linux I/O 調度器的工作機制是控制塊設備的請求隊列：確定隊列中哪些 I/O 的優先級更高以及何時下發 I/O 到塊設備，以此來減少磁盤尋道時間，從而提高系統的吞吐量。</p><p>目前 Linux 上有如下幾種 I/O 調度算法：</p><ol><li>noop - 通常用於內存存儲的設備。</li><li>cfq - 絕對公平調度器。進程平均使用IO帶寬。</li><li>Deadline - 針對延遲的調度器，每一個 I/O，都有一個最晚執行時間。</li><li>Anticipatory - 啓發式調度，類似 Deadline 算法，但是引入預測機制提高性能。</li></ol><p>查看設備當前的 I/O 調度器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/block/&lt;Disk_Name&gt;/queue/scheduler</span></span></code></pre></div><p>假設磁盤名稱是 <code>/dev/sdc</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/block/sdc/queue/scheduler</span></span>
<span class="line"><span>noop anticipatory deadline [cfq]</span></span></code></pre></div><h3 id="如何改變硬盤設備-i-o-調度器" tabindex="-1">如何改變硬盤設備 I/O 調度器 <a class="header-anchor" href="#如何改變硬盤設備-i-o-調度器" aria-label="Permalink to “如何改變硬盤設備 I/O 調度器”">​</a></h3><p>使用如下指令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo {SCHEDULER-NAME} &gt; /sys/block/&lt;Disk_Name&gt;/queue/scheduler</span></span></code></pre></div><p>比如設置 noop 調度器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo noop &gt; /sys/block/sdc/queue/scheduler</span></span></code></pre></div><p>以上設置重啓後會失效，要想重啓後配置仍生效，需要在內核啓動參數中將 <code>elevator=noop</code> 寫入 <code>/boot/grub/menu.lst</code>：</p><h4 id="_1-備份-menu-lst-文件" tabindex="-1">1. 備份 menu.lst 文件 <a class="header-anchor" href="#_1-備份-menu-lst-文件" aria-label="Permalink to “1. 備份 menu.lst 文件”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -p /boot/grub/menu.lst /boot/grub/menu.lst-backup</span></span></code></pre></div><h4 id="_2-更新-boot-grub-menu-lst" tabindex="-1">2. 更新 /boot/grub/menu.lst <a class="header-anchor" href="#_2-更新-boot-grub-menu-lst" aria-label="Permalink to “2. 更新 /boot/grub/menu.lst”">​</a></h4><p>將 <code>elevator=noop</code> 添加到文件末尾，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kernel /vmlinuz-2.6.16.60-0.91.1-smp root=/dev/sysvg/root splash=silent splash=off showopts elevator=noop</span></span></code></pre></div><hr>`,20)),l("p",null,[e[1]||(e[1]=s("via: ",-1)),t(i,{href:"http://linuxroutes.com/change-io-scheduler-linux/"},{default:a(()=>[...e[0]||(e[0]=[s("http://linuxroutes.com/change-io-scheduler-linux/",-1)])]),_:1})]),l("p",null,[e[5]||(e[5]=s("作者：",-1)),t(i,{href:"http://linuxroutes.com/change-io-scheduler-linux/"},{default:a(()=>[...e[2]||(e[2]=[s("UX Techno",-1)])]),_:1}),e[6]||(e[6]=s(" 譯者：",-1)),t(i,{href:"https://github.com/honpey"},{default:a(()=>[...e[3]||(e[3]=[s("honpey",-1)])]),_:1}),e[7]||(e[7]=s(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[10]||(e[10]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[s("LCTT",-1)])]),_:1}),e[11]||(e[11]=s(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[s("Linux中國",-1)])]),_:1}),e[12]||(e[12]=s(" 榮譽推出",-1))])])}const y=n(u,[["render",h]]);export{C as __pageData,y as default};
